INSERT INTO `faqs` VALUES (4,'What is Risk Management?','What is Risk Management?','<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Answer:</p>\r\n\r\n<p><em>Risk management is the identification, analysis and economic control of those risks which can threaten the assets or earning capacity of an enterprise.</em></p>\r\n\r\n<p>&nbsp;</p>','<p>Answer:</p>\r\n\r\n<p><em>Risk management is the identification, analysis and economic control of those risks which can threaten the assets or earning capacity of an enterprise.</em></p>\r\n\r\n<p>&nbsp;</p>',1,'what-is-risk-management','2022-08-11 11:13:11','2022-08-11 11:13:11',NULL);
